using VisualRelay.Domain;

namespace VisualRelay.Core.Queue;

/// <summary>
/// Sidecar record written to <c>.relay/restart-handoff.json</c> when a
/// RestartBetweenTasks drain stops at a committed-task boundary. The
/// relaunched instance reads it to resume the queue on the same repo.
/// </summary>
public sealed record RestartHandoff(
    string RootPath,
    string DrainId,
    DateTimeOffset Timestamp,
    int PendingCount,
    string? CommitSha)
{
    /// <summary>Writes the handoff sidecar under <paramref name="rootPath"/>.</summary>
    public static RestartHandoff Write(
        string rootPath,
        RelayTaskOutcome outcome,
        string drainId,
        int pendingCount)
    {
        var handoff = new RestartHandoff(
            rootPath, drainId, DateTimeOffset.UtcNow,
            pendingCount, outcome.CommitSha);
        var dir = Path.Combine(rootPath, ".relay");
        Directory.CreateDirectory(dir);
        File.WriteAllText(
            Path.Combine(dir, "restart-handoff.json"),
            System.Text.Json.JsonSerializer.Serialize(handoff));
        return handoff;
    }

    /// <summary>Reads the handoff sidecar, or null when absent.</summary>
    public static RestartHandoff? Read(string rootPath)
    {
        var path = Path.Combine(rootPath, ".relay", "restart-handoff.json");
        if (!File.Exists(path)) return null;
        var json = File.ReadAllText(path);
        return System.Text.Json.JsonSerializer.Deserialize<RestartHandoff>(json);
    }

    /// <summary>Deletes the handoff sidecar unconditionally.</summary>
    public static void Delete(string rootPath)
    {
        var path = Path.Combine(rootPath, ".relay", "restart-handoff.json");
        if (File.Exists(path)) File.Delete(path);
    }

    /// <summary>
    /// Renames the sidecar to <c>.consumed</c> so the restart-resume logic
    /// knows it was already picked up.
    /// </summary>
    public static void MarkConsumed(string rootPath)
    {
        var path = Path.Combine(rootPath, ".relay", "restart-handoff.json");
        if (File.Exists(path))
            File.Move(path, path + ".consumed");
    }

    /// <summary>
    /// Returns true when the handoff is older than 5 minutes or its
    /// <see cref="RootPath"/> no longer exists on disk.
    /// </summary>
    public static bool IsStale(RestartHandoff handoff, DateTimeOffset now)
    {
        if (!Directory.Exists(handoff.RootPath)) return true;
        return (now - handoff.Timestamp).TotalMinutes > 5;
    }
}

namespace VisualRelay.Core.Queue;

// ReSharper disable once UnusedType.Global — partial of RelayQueueController
public sealed partial class RelayQueueController
{
    /// <summary>
    /// When set, invoked at the RestartBetweenTasks boundary after a committed
    /// task with the written <see cref="RestartHandoff"/>. The subscriber
    /// (usually the ViewModel) should trigger app shutdown + relaunch.
    /// </summary>
    public Action<RestartHandoff>? OnRestartRequested { get; set; }
}

using VisualRelay.Core.Queue;
using VisualRelay.Domain;

namespace VisualRelay.Tests;

/// <summary>
/// Tests for the RestartBetweenTasks Run All protocol — drain stops after
/// committed tasks, writes a handoff sidecar, and the relaunched instance
/// resumes where it left off.
/// </summary>
public sealed class RelayQueueControllerRestartTests
{
    [Fact]
    public async Task RestartBetweenTasks_CommittedTask_StopsAndWritesHandoff()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);
        repo.WriteTask("alpha", "# Alpha\n");
        repo.WriteTask("beta", "# Beta\n");

        // Both tasks return Committed — but RestartBetweenTasks must stop after
        // the first committed task so the relaunched build picks up the new code.
        var runner = new ScriptedOutcomeTaskRunner(
            new RelayTaskOutcome("alpha", RelayTaskOutcomeStatus.Committed, "hash-a", "sha-a", null),
            new RelayTaskOutcome("beta", RelayTaskOutcomeStatus.Committed, "hash-b", "sha-b", null));

        RestartHandoff? capturedHandoff = null;
        var controller = new RelayQueueController(repo.Root, runner);
        controller.OnRestartRequested = h => capturedHandoff = h;

        await controller.RefreshAsync();
        var results = await controller.DrainAsync(mode: RunAllMode.RestartBetweenTasks);

        // Only alpha ran — RestartBetweenTasks stops at the first committed task.
        Assert.Single(results);
        Assert.Equal("alpha", results[0].TaskId);
        Assert.Equal(RelayTaskOutcomeStatus.Committed, results[0].Status);

        // Handoff sidecar must exist so the relaunched instance can resume.
        Assert.True(File.Exists(Path.Combine(repo.Root, ".relay", "restart-handoff.json")));

        // OnRestartRequested callback must have been invoked exactly once.
        Assert.NotNull(capturedHandoff);
        Assert.Equal(repo.Root, capturedHandoff!.RootPath);
        Assert.Equal("sha-a", capturedHandoff.CommitSha);
        Assert.Equal(1, capturedHandoff.PendingCount);

        // Beta must not have run (it's pending for the relaunched instance).
        Assert.DoesNotContain("beta", runner.TasksRun);
    }

    [Fact]
    public async Task RestartBetweenTasks_FlaggedTask_NoHandoff_CommitsTriggerAfter()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);
        repo.WriteTask("alpha", "# Alpha — will flag\n");
        repo.WriteTask("beta", "# Beta — commits after flag\n");

        // Alpha flags (no code change → no restart needed).
        // Beta commits → handoff + stop so the relaunched build picks it up.
        var runner = new ScriptedOutcomeTaskRunner(
            new RelayTaskOutcome("alpha", RelayTaskOutcomeStatus.Flagged, null, null, "author-tests did not go red"),
            new RelayTaskOutcome("beta", RelayTaskOutcomeStatus.Committed, "hash-b", "sha-b", null));

        RestartHandoff? capturedHandoff = null;
        var controller = new RelayQueueController(repo.Root, runner);
        controller.OnRestartRequested = h => capturedHandoff = h;

        await controller.RefreshAsync();
        var results = await controller.DrainAsync(mode: RunAllMode.RestartBetweenTasks);

        // Both tasks ran: flagged alpha in-process, then committed beta triggers restart.
        Assert.Equal(2, results.Count);
        Assert.Equal("alpha", results[0].TaskId);
        Assert.Equal(RelayTaskOutcomeStatus.Flagged, results[0].Status);
        Assert.Equal("beta", results[1].TaskId);
        Assert.Equal(RelayTaskOutcomeStatus.Committed, results[1].Status);

        // Handoff must exist for beta's commit.
        Assert.True(File.Exists(Path.Combine(repo.Root, ".relay", "restart-handoff.json")));

        // Callback must have been called exactly once (for beta, not alpha).
        Assert.NotNull(capturedHandoff);
        Assert.Equal("sha-b", capturedHandoff!.CommitSha);
    }

    [Fact]
    public async Task RestartBetweenTasks_StartupHandoffConsumed_NoProgressGuard()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);
        repo.WriteTask("alpha", "# Alpha — flags, no progress\n");

        // Simulate a restart cycle: a handoff exists from the prior launch.
        var priorHandoff = RestartHandoff.Write(
            repo.Root,
            new RelayTaskOutcome("prior", RelayTaskOutcomeStatus.Committed, "h", "sha-prior", null),
            "drain-20260716000000",
            pendingCount: 1);
        Assert.True(File.Exists(Path.Combine(repo.Root, ".relay", "restart-handoff.json")));

        // The only task flags — zero committed outcomes this cycle.
        var runner = new ScriptedOutcomeTaskRunner(
            new RelayTaskOutcome("alpha", RelayTaskOutcomeStatus.Flagged, null, null, "failed"));

        var restartRequested = false;
        var controller = new RelayQueueController(repo.Root, runner);
        controller.OnRestartRequested = _ => restartRequested = true;

        await controller.RefreshAsync();
        var results = await controller.DrainAsync(mode: RunAllMode.RestartBetweenTasks);

        // Zero committed outcomes → no restart, no new handoff.
        Assert.DoesNotContain(results, r => r.Status == RelayTaskOutcomeStatus.Committed);
        Assert.False(restartRequested);

        // The handoff must have been consumed so the next launch won't auto-resume.
        Assert.False(File.Exists(Path.Combine(repo.Root, ".relay", "restart-handoff.json")));

        // Drain ends cleanly — not stalled in a restart loop.
        Assert.Equal(RelayQueueState.ReviewNeeded, controller.State);
    }
}

using VisualRelay.Core.Queue;
using VisualRelay.Domain;

namespace VisualRelay.Tests;

/// <summary>
/// Headless / structural tests for the Restart Between Tasks dropdown UI
/// in TopBar.axaml.  Verifies that the three protocols render with names
/// and descriptions, navigation and accessibility stay intact.
/// </summary>
public sealed class RestartBetweenTasksUiTests
{
    private static string ReadTopBarAxaml()
    {
        var paths = RepoPaths.Resolve();
        return File.ReadAllText(
            Path.Combine(paths.Root, "src", "VisualRelay.App", "Views", "Controls",
                "TopBar.axaml"));
    }

    [Fact]
    public void Dropdown_ContainsAllThreeModes_WithDescriptions()
    {
        var axaml = ReadTopBarAxaml();

        // Every protocol name must appear somewhere in the template.
        Assert.Contains("Standard", axaml, StringComparison.Ordinal);
        Assert.Contains("Sequential", axaml, StringComparison.Ordinal);
        Assert.Contains("Restart Between Tasks", axaml, StringComparison.Ordinal);

        // Each protocol must have a description line in the item template.
        Assert.Contains("Plan all tasks up front, then execute",
            axaml, StringComparison.Ordinal);
        Assert.Contains("One task at a time, checking for new tasks between",
            axaml, StringComparison.Ordinal);
        Assert.Contains("Sequential, plus the app rebuilds and relaunches after each committed task",
            axaml, StringComparison.Ordinal);

        // The ComboBox must have an ItemTemplate so each item renders
        // name + description as a two-line layout.
        Assert.Contains("ItemTemplate", axaml, StringComparison.Ordinal);
    }

    [Fact]
    public void Dropdown_ToolTip_CoversAllThreeModes()
    {
        var axaml = ReadTopBarAxaml();

        // The ToolTip must mention all three modes.
        Assert.Contains("Standard", axaml, StringComparison.Ordinal);
        Assert.Contains("Sequential", axaml, StringComparison.Ordinal);
        Assert.Contains("Restart", axaml, StringComparison.Ordinal);
    }

    [Fact]
    public void Dropdown_RetainsAccessibility()
    {
        var axaml = ReadTopBarAxaml();

        // The ComboBox must remain keyboard-navigable and screen-reader friendly.
        // AutomationProperties.Name on items ensures screen readers announce the
        // protocol name even when the collapsed control shows only the name.
        Assert.Contains("AutomationProperties.Name", axaml, StringComparison.Ordinal);
    }

    [Fact]
    public void RunAllModeDropdown_BindsToAllThreeOptions()
    {
        var axaml = ReadTopBarAxaml();

        // The ComboBox must bind to RunAllModeOptions and SelectedRunAllMode.
        Assert.Contains("RunAllModeOptions", axaml, StringComparison.Ordinal);
        Assert.Contains("SelectedRunAllMode", axaml, StringComparison.Ordinal);
    }
}

